const row = $json;
const text = (value) => value == null ? '' : String(value).trim();
const upper = (value) => text(value).toUpperCase();
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = Math.floor(Math.random() * 16);
  return (c === 'x' ? r : ((r & 3) | 8)).toString(16);
});
const csvRequired = (value) =>
  text(value).split(',').map((v) => upper(v)).filter(Boolean);
const csvAligned = (value) =>
  text(value) === '' ? [] : String(value).split(',').map((v) => upper(v));

const status = text(row['Processing Status']).toLowerCase();
const operation = text(row['Operation']);
const formResponseId = text(row['Form Response ID']);
const retryCountValue = Number(row['Retry Count'] || 0);

const queue = {
  formResponseId,
  retryCount: Number.isFinite(retryCountValue) ? retryCountValue : 0,
  incomingStatus: status,
  operation,
};

const processable =
  status === 'pending' &&
  operation === 'enrollment.submit';

if (!processable) {
  return {
    json: {
      processable: false,
      queue,
      skipReason:
        status !== 'pending'
          ? 'QUEUE_ROW_NOT_PENDING'
          : 'QUEUE_OPERATION_MISMATCH',
    },
  };
}

if (!formResponseId) {
  throw new Error('VALIDATION_FORM_RESPONSE_ID_REQUIRED');
}

let raw = row['Raw Response JSON'];
if (typeof raw === 'string') {
  try {
    raw = JSON.parse(raw);
  } catch {
    throw new Error('VALIDATION_RAW_RESPONSE_JSON');
  }
}

if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
  throw new Error('VALIDATION_RAW_RESPONSE_OBJECT');
}

const get = (title) => text(raw[title]);
const courseCodes = csvRequired(
  get('Requested course or subject codes (comma-separated)')
);
const preferredSectionCodes = csvAligned(
  get('Preferred section codes in the same order (optional, comma-separated)')
);

if (courseCodes.length === 0) {
  throw new Error('VALIDATION_COURSE_CODES_REQUIRED');
}

if (new Set(courseCodes).size !== courseCodes.length) {
  throw new Error('VALIDATION_DUPLICATE_COURSE_CODE');
}

if (
  preferredSectionCodes.length > 0 &&
  preferredSectionCodes.length !== courseCodes.length
) {
  throw new Error('VALIDATION_SECTION_ALIGNMENT');
}

const correlationId = uuid();
const idempotencyKey =
  text(row['Idempotency Key']) ||
  `google-form:${text(row['Source Form ID'])}:${formResponseId}`;
const submittedAt =
  text(row['Submitted At UTC']) || new Date().toISOString();

const request = {
  operation: 'enrollment.submit',
  correlation_id: correlationId,
  idempotency_key: idempotencyKey,
  requester: {
    email: text(row['Respondent Email']),
    type: 'google_form_respondent',
  },
  submitted_at: submittedAt,
  source: {
    channel: 'google_forms',
    source_submission_id: formResponseId,
    source_form_id: text(row['Source Form ID']),
    source_spreadsheet_id: text(row['Source Spreadsheet ID']),
  },
  payload: {
    institution_code: upper(get('Institution code')),
    campus_code: upper(get('Campus code')),
    student_number: upper(get('Student number')),
    program_code: upper(get('Program or qualification code')),
    term_code: upper(get('Term or semester code')),
    course_codes: courseCodes,
    preferred_section_codes: preferredSectionCodes,
    allow_fallback:
      get(
        'Allow another valid section when the preferred section is unavailable?'
      ).toLowerCase() === 'yes',
    request_notes: get('Enrollment notes'),
  },
};

return { json: { processable: true, queue, request } };

const source = $('Normalize Enrollment Queue Row').item.json;
const raw = $json ?? {};

let body = Object.prototype.hasOwnProperty.call(raw, 'body')
  ? raw.body
  : raw;

if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    body = { message: body };
  }
}

if (
  Array.isArray(body) &&
  body.length === 1 &&
  body[0] &&
  typeof body[0] === 'object'
) {
  body = body[0];
}

const statusValue = raw.statusCode ?? raw.status ?? null;
const statusCode =
  statusValue == null
    ? (raw.error ? 0 : 200)
    : Number(statusValue);

const transportError =
  typeof raw.error === 'string'
    ? raw.error
    : (raw.error?.message || raw.message || '');

const bodyError =
  body && typeof body === 'object'
    ? (
        body.error && typeof body.error === 'object'
          ? body.error
          : body
      )
    : {};

const rpcSuccess =
  statusCode >= 200 &&
  statusCode < 300 &&
  body &&
  typeof body === 'object' &&
  body.success === true;

const errorCode = rpcSuccess
  ? ''
  : String(
      bodyError.code ||
      bodyError.error_code ||
      (statusCode > 0 ? `HTTP_${statusCode}` : 'NETWORK_FAILURE')
    ).slice(0, 100);

const errorMessage = rpcSuccess
  ? ''
  : String(
      bodyError.message ||
      bodyError.error_message ||
      transportError ||
      'The enrollment operation could not be completed.'
    ).slice(0, 300);

const now = new Date().toISOString();

return {
  json: {
    'Form Response ID': source.queue.formResponseId,
    'Processing Status': rpcSuccess ? 'completed' : 'failed',
    'Processed At UTC': now,
    'Correlation ID':
      body?.correlation_id || source.request.correlation_id,
    'Error Code': errorCode,
    'Error Message': errorMessage,
    'Retry Count':
      source.queue.retryCount + (rpcSuccess ? 0 : 1),
    'Last Attempt At UTC': now,
    'n8n Execution ID': $execution.id,
    rpcResult: body,
    httpStatusCode: statusCode,
    success: rpcSuccess,
  },
};
